+                Ok(ScriptedTransport {
+                    gets: VecDeque::from([
+                        serde_json::json!({"head": {"sha": HEAD}}),
+                        returned("exact body"),
+                        serde_json::json!({"head": {"sha": HEAD}}),
+                    ]),
+                    sends: VecDeque::from([
